#!/usr/bin/env python3
"""
Round 132b (culprits), 2 October 2026. Needs round 131b.

Crops, cropland spread, meat, deforestation promises and oceans rearranged.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 132b (2 October)\n\nNeeds round 131b. Tiles patch round132b_tiles.py beside it. No app.js?v= bump.\n\n- Cropland spread: potapov_cropland shows only net gain and net loss\n  (choiceMatch, a new filter on rows that read a build\'s list of chips).\n- Every SPAM 2020 crop is its own row (spam_<code>, 38 new) under its crop\n  in By crop, alphabetical, the "other" groups last; crops_spam and\n  crop_coffee (its files never existed in SPAM 2020) in PANEL_REMOVED.\n  SPAM\'s COFF entry is titled as its general coffee entry, kinds unstated.\n- Meat: Trase\'s chickens and pigs slaughtered and beef produced (Brazil) and\n  Paraguay\'s cattle herd size taken out (CATALOGUE_BY_TITLE); Cattle and\n  pasture and Pigs and chickens headings gone; Herds above Facilities; Marine\n  meats (Wild-caught fish: fishing, iuu_vessels, iuu_positions; Fish and\n  shrimp farms: aquaculture_ponds, ponds).\n- Deforestation promises (h4 under Deforestation): every zero-deforestation\n  share, beef, soy, cocoa and palm (corn stays out).\n- Oceans: Every human impact together first; the kinds of harm under it as\n  h5, each with a tag (new heading option `tag`) saying whether that layer\n  counts it; Pollution at sea (wastewater plumes, slicks, sunken ships,\n  plastic); a note pointing to Meat and Pollution. ocean_heat split: sea\n  temperature only; ocean_bleaching (bleaching alert and degree heating\n  weeks, same files) under Reefs and mangroves. Dead zones also under\n  Biodiversity loss > Fish; deep-sea mining also under Mining.\n- Tiles: oceans_more.py heat falls back to Coral Reef Watch\'s own server;\n  acid looks through sub-folders and logs every file it finds; shipping is\n  its own script, ocean_shipping.py, with a 120-minute budget per run.\n\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round132b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 131b" not in h.read_text(encoding="utf-8"):
        sys.exit("round132b: round 131b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round132b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round132b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round132b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
